import{f as a,o as n,c as t,a2 as s}from"./chunks/framework.n5RLHRfo.js";const m=JSON.parse('{"title":"LOD (Level of Detail)","description":"","frontmatter":{"title":"LOD (Level of Detail)","order":9},"headers":[],"relativePath":"en/lod/index.md","filePath":"en/lod/index.md","lastUpdated":1792993711000}'),r={name:"en/lod/index.md"};function l(o,e,i,d,h,c){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="lod" tabindex="-1">LOD <a class="header-anchor" href="#lod" aria-label="Permalink to &quot;LOD&quot;">​</a></h1><p><strong>LOD</strong> (Level of Detail) is an optimization technique that shows different levels of detail (Geometry) depending on the distance between the camera and the object. By using high-resolution models for objects that are close and low-resolution models for objects that are far away, you can maximize rendering performance while maintaining visual quality.</p><p>RedGPU supports LOD in a consistent way by embedding <strong><a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Display/namespaces/CoreMesh/classes/LODManager.html"><code>LODManager</code></a></strong> in both <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Display/classes/Mesh.html"><code>Mesh</code></a> and <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Display/classes/InstancingMesh.html"><code>InstancingMesh</code></a>.</p><h2 id="learning-guide" tabindex="-1">Learning Guide <a class="header-anchor" href="#learning-guide" aria-label="Permalink to &quot;Learning Guide&quot;">​</a></h2><p>The way LOD works differs depending on the object type. Refer to the document that suits your situation.</p><ol><li><strong><a href="./mesh-lod.html">Mesh LOD</a></strong>: Applied to general single objects (CPU-based)</li><li><strong><a href="./instanced-lod.html">Instancing Mesh LOD</a></strong>: Applied to massive instancing objects (GPU-based)</li></ol><hr><h2 id="related-examples" tabindex="-1">Related Examples <a class="header-anchor" href="#related-examples" aria-label="Permalink to &quot;Related Examples&quot;">​</a></h2><ul><li><a href="/RedGPU/examples/3d/lod/MeshCPULOD/" target="_blank" rel="noopener noreferrer">Mesh CPU LOD</a></li><li><a href="/RedGPU/examples/3d/lod/MeshCPULOD_material/" target="_blank" rel="noopener noreferrer">Mesh CPU LOD (Per-Level Material)</a></li><li><a href="/RedGPU/examples/3d/lod/InstanceMeshGPULOD/" target="_blank" rel="noopener noreferrer">InstancingMesh GPU LOD</a></li><li><a href="/RedGPU/examples/3d/lod/InstanceMeshGPULOD_material/" target="_blank" rel="noopener noreferrer">InstancingMesh GPU LOD (Per-Level Material)</a></li></ul><hr><p><a href="./mesh-lod.html">Next Step: Learn Mesh LOD</a></p>',11)])])}const f=a(r,[["render",l]]);export{m as __pageData,f as default};
